import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.DYAmjhAm.js";const g=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/performance.md","filePath":"guide/performance.md","lastUpdated":1789754513000}'),n={name:"guide/performance.md"};function o(r,e,h,d,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>Breeze does a lot per entity: change tracking, validation, relationship fixup, key management, events. Most applications never need to think about it. When you do — a grid over thousands of rows, a bulk import, a generated data set — it helps to know which parts are expensive, because the answers are not where people usually look.</p><p>Everything below is measured, not estimated. See <a href="#how-these-were-measured">How these were measured</a>.</p><h2 id="what-an-operation-costs" tabindex="-1">What an operation costs <a class="header-anchor" href="#what-an-operation-costs" aria-label="Permalink to &quot;What an operation costs&quot;">​</a></h2><p>Per entity, using the Northwind <code>Order</code> type (14 data properties, 4 navigation properties):</p><table tabindex="0"><thead><tr><th>operation</th><th>cost</th><th>made up of</th></tr></thead><tbody><tr><td><code>em.createEntity(&#39;Order&#39;)</code></td><td>~9 µs</td><td>building it ~1.8 µs, <strong>attaching it to the manager ~7.4 µs</strong></td></tr><tr><td>the same entity from a query</td><td>~6 µs</td><td>queries skip validation and batch their events</td></tr><tr><td>setting a tracked property</td><td>~0.7 µs</td><td><strong>96% change tracking</strong>, ~2% the backing store</td></tr><tr><td>reading a tracked property</td><td>~9 ns</td><td>an accessor over a plain object</td></tr><tr><td>relating two entities</td><td>~3 µs</td><td>the same either way you say it — see below</td></tr></tbody></table><p>Two things follow. Attaching to an <code>EntityManager</code> costs several times more than creating the object, and setting a property is almost entirely change tracking — the property accessors themselves barely register.</p><h2 id="automatic-validation" tabindex="-1">Automatic validation <a class="header-anchor" href="#automatic-validation" aria-label="Permalink to &quot;Automatic validation&quot;">​</a></h2><p>Validation is the largest single cost in change tracking:</p><table tabindex="0"><thead><tr><th>option</th><th>default</th><th>share of the operation</th></tr></thead><tbody><tr><td><code>validateOnPropertyChange</code></td><td><code>true</code></td><td>about <strong>63%</strong> of setting a tracked property</td></tr><tr><td><code>validateOnAttach</code></td><td><code>true</code></td><td>about <strong>38%</strong> of attaching an entity</td></tr></tbody></table><p>For ordinary screens that is a good trade and you should leave it alone. For a loop over thousands of entities it is the first thing to turn off — then validate deliberately at the end:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> saved</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> em.validationOptions;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setProperties</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  validationOptions: saved.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ validateOnPropertyChange: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, validateOnAttach: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ... build or edit many entities ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">finally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setProperties</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ validationOptions: saved });</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getEntities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forEach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> e.entityAspect.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">validateEntity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// once, at the end</span></span></code></pre></div><p><code>validateOnSave</code> is different: it runs once per changed entity at save time, and turning it off means sending data the server may reject. Leave it on. See <a href="/breeze-client-v3/guide/validation">Validation</a>.</p><h2 id="let-queries-build-entities" tabindex="-1">Let queries build entities <a class="header-anchor" href="#let-queries-build-entities" aria-label="Permalink to &quot;Let queries build entities&quot;">​</a></h2><p>An entity that arrives from a query costs about half what the same entity costs through <code>createEntity</code>, because the loading path suppresses per-property events and does not validate (unless you turn on <code>validateOnQuery</code>). If you have a choice between querying data and constructing the equivalent entities in a loop, query.</p><h2 id="collections-are-created-on-first-read" tabindex="-1">Collections are created on first read <a class="header-anchor" href="#collections-are-created-on-first-read" aria-label="Permalink to &quot;Collections are created on first read&quot;">​</a></h2><p>A collection navigation - <code>order.orderDetails</code> - is an empty relation array until something reads it. Creating one costs about 0.5 µs and 400 bytes, including the array&#39;s <code>arrayChanged</code> event, and most collections on most entities are never touched, so an entity only pays for the ones it uses.</p><p>Measured over 50,000 attached entities, each type in its own process:</p><table tabindex="0"><thead><tr><th>type</th><th>collection navigations</th><th>eager</th><th>lazy</th></tr></thead><tbody><tr><td><code>Order</code></td><td>1</td><td>3,285 B</td><td>2,909 B</td></tr><tr><td><code>Customer</code></td><td>1</td><td>3,590 B</td><td>3,190 B</td></tr><tr><td><code>Employee</code></td><td>3</td><td>5,822 B</td><td>3,927 B</td></tr></tbody></table><p>Building a detached entity drops from about 1.74 µs to 1.18 µs with it. Attaching one is unchanged - that cost is validation and manager bookkeeping, not collections.</p><p>The array is created on the first read and kept, so its identity is stable from then on:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order.orderDetails;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order.orderDetails;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// the same array</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(detail);                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// and normal in every other way</span></span></code></pre></div><p>Reading is the only thing that creates it. Attaching an entity, deleting one, validating one or propagating a key change all skip collections that do not exist yet - there is nothing in an uncreated collection for any of them to act on. A query creates only the collections its payload actually carries.</p><h2 id="relating-entities" tabindex="-1">Relating entities <a class="header-anchor" href="#relating-entities" aria-label="Permalink to &quot;Relating entities&quot;">​</a></h2><p>The three ways of saying it cost the same, because they all end in the same place — each sets the other, and the recursion is cut off once the state is consistent:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">customer.orders.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(order);              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~3.2 µs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">order.customer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customer;                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~3.2 µs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">order.customerID </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customer.customerID;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~2.7 µs</span></span></code></pre></div><p>About 4× a plain property set, for two entities updated, a foreign key kept in step, and the events. Pick whichever reads best.</p><p>Adding to a collection does not get slower as the collection fills: Breeze checks the child&#39;s own back-reference rather than searching the array, so a push into a 16,000-element collection costs what a push into an empty one does.</p><p><strong>Moving a child from one parent to another</strong> is the exception. Breeze has to find it in the old parent&#39;s collection and take it out, and removing from the front of a large array shifts everything after it. Re-parenting thousands of children one at a time is around 4× the cost of attaching the same children to a parent for the first time. If you are reassigning a large collection wholesale, it is cheaper to detach the old parent than to move each child.</p><p><strong>Emptying a collection</strong> — which is what detaching or deleting the parent does — is one operation, not one per child. All the children are unparented, the collection is truncated in one go, and a single <code>arrayChanged</code> is published carrying every one of them. Detaching a customer with 16,000 orders takes about 6 ms.</p><div class="tip custom-block"><p class="custom-block-title">One event, not one per child</p><p>If you subscribe to <code>arrayChanged</code>, a detach or delete gives you a single notification whose <code>removed</code> holds the whole collection. Handle it as a batch rather than assuming one entity per event — the same as for the adds a query produces.</p></div><h2 id="cache-operations-scale-with-what-you-touch-not-with-what-is-cached" tabindex="-1">Cache operations scale with what you touch, not with what is cached <a class="header-anchor" href="#cache-operations-scale-with-what-you-touch-not-with-what-is-cached" aria-label="Permalink to &quot;Cache operations scale with what you touch, not with what is cached&quot;">​</a></h2><p>Accepting, rejecting or detaching entities one at a time costs the same whether the manager holds a hundred entities or a hundred thousand:</p><table tabindex="0"><thead><tr><th>over 40,000 changed entities</th><th></th></tr></thead><tbody><tr><td><code>entityAspect.acceptChanges()</code> each</td><td>~33 ms</td></tr><tr><td><code>entityAspect.rejectChanges()</code> each</td><td>~61 ms</td></tr><tr><td><code>em.detachEntity()</code> each</td><td>~66 ms</td></tr></tbody></table><p>So the ordinary idiom is fine:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getChanges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forEach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> e.entityAspect.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">acceptChanges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p><code>em.hasChanges()</code> is a flag, not a search, so you can bind it to a Save button and read it as often as you like. <code>em.getChanges()</code> and <code>em.getEntities()</code> do look at every cached entity of the types you ask for — cheap, about 0.4 ms over 20,000, but not free, so don&#39;t call them inside a loop over the result.</p><p>Looking an entity up by key is a hash lookup:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">em.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getEntityByKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Customer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ALFKI&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~150 ns, whatever the cache holds</span></span></code></pre></div><h2 id="related-entities-in-bulk" tabindex="-1">Related entities in bulk <a class="header-anchor" href="#related-entities-in-bulk" aria-label="Permalink to &quot;Related entities in bulk&quot;">​</a></h2><p><a href="/breeze-client-v3/api/interfaces/HasEntityGraph"><code>getEntityGraph</code></a>, from the <code>breeze-client/mixin-get-entity-graph</code><a href="/breeze-client-v3/guide/extensions#entity-graphs">optional extension</a>, indexes the children by their foreign key once per expand segment, so a deep expand is linear in the entities it returns:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client/mixin-get-entity-graph&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { HasEntityGraph } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client/mixin-get-entity-graph&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// a customer, its 8,000 orders and their 24,000 details: about 10 ms</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> graph</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (em </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HasEntityGraph</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getEntityGraph</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(customer, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;orders.orderDetails&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="reads-are-cheap" tabindex="-1">Reads are cheap <a class="header-anchor" href="#reads-are-cheap" aria-label="Permalink to &quot;Reads are cheap&quot;">​</a></h2><p>Reading a tracked property goes through an accessor on the prototype to a plain backing object: about 9 ns, or 1.7× a direct property read. Iterating results, reading properties in a template or a grid cell renderer — none of that needs avoiding.</p><p>The collections are real arrays, so <code>forEach</code>, <code>map</code>, indexing and spreading are the engine&#39;s native operations rather than anything Breeze interposes on.</p><h2 id="events-cost-almost-nothing-when-nobody-is-listening" tabindex="-1">Events cost almost nothing when nobody is listening <a class="header-anchor" href="#events-cost-almost-nothing-when-nobody-is-listening" aria-label="Permalink to &quot;Events cost almost nothing when nobody is listening&quot;">​</a></h2><p>Every entity carries two events — <code>propertyChanged</code> and <code>validationErrorsChanged</code> — and the manager carries three more. On a property set, subscribers account for about 66 ns of ~1.2 µs; publishing to an event with no subscribers costs around 30 ns, and the hot path skips even that.</p><p>Subscribe freely. What is worth knowing is the shape of what you get:</p><ul><li><strong><code>propertyChanged</code> and <code>entityChanged</code>/<code>PropertyChange</code> are one-to-one.</strong> No event is published twice for one change.</li><li><strong>Relating two entities changes two properties</strong>, the navigation property and the foreign key, so it publishes two of each — whichever of the three ways you write it.</li><li><strong>The entity&#39;s own event comes before the manager&#39;s</strong>, for both property changes and validation.</li><li><strong>Setting a property to the value it already has publishes nothing.</strong></li></ul><p>An event object is 40 bytes, so the two on each entity are a negligible part of the ~2.6 KB a cached entity occupies.</p><h2 id="what-an-entitymanager-holds-on-to" tabindex="-1">What an EntityManager holds on to <a class="header-anchor" href="#what-an-entitymanager-holds-on-to" aria-label="Permalink to &quot;What an EntityManager holds on to&quot;">​</a></h2><p>Entities leave the cache cleanly. Detaching one, clearing the manager, rejecting an <code>Added</code> entity&#39;s changes, or dropping the manager itself all release the entity and everything only it reached — including when another manager is sharing the same <code>MetadataStore</code>, and when the entity had a live <code>propertyChanged</code> subscription. <code>test/retention/</code> asserts each of those against a real garbage collection rather than a heap-size threshold, so they cannot quietly stop being true.</p><p>Two things are retained on purpose, both bounded:</p><ul><li><strong>The last entity to fail each validator.</strong> A failed <code>validate()</code> keeps its context, because <code>getMessage()</code> reads it. The next failure on that validator replaces it, so the cost is one entity per validator, not one per failure. A validation that <em>passes</em> keeps nothing.</li><li><strong>A child waiting for a parent that never arrived</strong>, but only while it is attached. It sits in the manager&#39;s unattached-children map so it can be linked if that parent shows up later. Detaching the child removes it.</li></ul><p>One thing grows with use:</p><ul><li><p><strong>The key generator remembers every temporary id it has issued</strong>, so that importing an entity that carries one cannot collide with a live entity. Nothing prunes it, so the set is proportional to the entities a manager has <em>ever created</em>, not to the entities in its cache — a manager that creates and saves a hundred rows a minute for a day will hold a few million short strings. It holds strings, not entities, so nothing else is pinned.</p><p><code>clear()</code> replaces the key generator outright, which is the lever if you keep one manager alive indefinitely. A manager per screen, or per unit of work, never gets near it.</p></li></ul><h2 id="bundle-size" tabindex="-1">Bundle size <a class="header-anchor" href="#bundle-size" aria-label="Permalink to &quot;Bundle size&quot;">​</a></h2><p>The package is side-effect free apart from the entity-graph mixin, so a bundler drops what you do not use. Bundled with Vite from the published package, unminified:</p><table tabindex="0"><thead><tr><th>the app imports</th><th>bundle</th></tr></thead><tbody><tr><td><code>MetadataStore</code> only</td><td>330 KB</td></tr><tr><td><code>EntityManager</code></td><td>455 KB</td></tr><tr><td><code>EntityManager</code> + <code>breeze-client/mixin-get-entity-graph</code></td><td>460 KB</td></tr></tbody></table><p>Minified, a typical application — core plus the three standard adapters — is about 168 KB, or 46 KB gzipped. Import the <a href="/breeze-client-v3/guide/configuration">adapter subpaths</a> you use rather than pulling in ones you do not.</p><h2 id="how-these-were-measured" tabindex="-1">How these were measured <a class="header-anchor" href="#how-these-were-measured" aria-label="Permalink to &quot;How these were measured&quot;">​</a></h2><p>Node 24, 20,000 entities per run, each variant in its own process so that one shape does not pollute another&#39;s inline caches. Ratios are more durable than absolute figures: your engine, your metadata and the number of validators on your properties all move the numbers, and a micro-benchmark never matches an application exactly. Measure your own workload before optimising it — and be prepared for the answer to be somewhere other than where you expected, which is how this page came about.</p>`,62)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
